--
-- Table structure for table `cms_section_items`
--

DROP TABLE IF EXISTS `cms_section_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cms_section_items` (
  `item_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `section_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subtitle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `href` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `variant_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `blog_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `metadata` json DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`item_id`),
  KEY `idx_cms_section_items_section` (`section_id`),
  KEY `idx_cms_section_items_product` (`product_id`),
  KEY `idx_cms_section_items_variant` (`variant_id`),
  KEY `idx_cms_section_items_blog` (`blog_id`),
  KEY `idx_cms_section_items_active_sort` (`section_id`,`is_active`,`sort_order`),
  CONSTRAINT `fk_cms_section_items_blog` FOREIGN KEY (`blog_id`) REFERENCES `blog_posts` (`post_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cms_section_items_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cms_section_items_section` FOREIGN KEY (`section_id`) REFERENCES `cms_sections` (`section_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cms_section_items_variant` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`variant_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `cms_section_items`
--

LOCK TABLES `cms_section_items` WRITE;
/*!40000 ALTER TABLE `cms_section_items` DISABLE KEYS */;
