DROP TABLE IF EXISTS `cms_sections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cms_sections` (
  `section_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `collection_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `section_type` enum('BANNER','SHORTCUT_BUTTONS','SHORTCUT_CARDS','FEATURED_PRODUCTS','BLOG_GRID','PRODUCT_GRID') COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subtitle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `background_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `href` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `metadata` json DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`section_id`),
  KEY `idx_cms_sections_collection` (`collection_id`),
  KEY `idx_cms_sections_type` (`section_type`),
  KEY `idx_cms_sections_active_sort` (`collection_id`,`is_active`,`sort_order`),
  CONSTRAINT `fk_cms_sections_collection` FOREIGN KEY (`collection_id`) REFERENCES `cms_collections` (`collection_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

