DELIMITER ;;
/*!50003 CREATE*/ /*!50003 TRIGGER `trg_orders_after_update` AFTER UPDATE ON `orders` FOR EACH ROW BEGIN
    -- Chuyển sang các trạng thái hoàn kho
    IF OLD.status NOT IN ('CANCELLED', 'RETURNED', 'DELIVERY_FAILED') 
       AND NEW.status IN ('CANCELLED', 'RETURNED', 'DELIVERY_FAILED') THEN
        UPDATE product_variants pv
        JOIN orders_details od ON pv.variant_id = od.variant_id
        SET pv.quantity_in_stock = pv.quantity_in_stock + od.quantity,
            pv.sold_quantity = pv.sold_quantity - od.quantity
        WHERE od.order_id = NEW.order_id;

        INSERT INTO inventory_transactions (
            transaction_id,
            variant_id,
            order_id,
            type,
            quantity,
            before_quantity,
            after_quantity,
            note,
            created_by
        )
        SELECT
            UUID(),
            od.variant_id,
            NEW.order_id,
            'RELEASE',
            od.quantity,
            pv.quantity_in_stock - od.quantity,
            pv.quantity_in_stock,
            CONCAT('Auto stock release when order status changed from ', OLD.status, ' to ', NEW.status),
            NEW.employee_id
        FROM orders_details od
        JOIN product_variants pv ON pv.variant_id = od.variant_id
        WHERE od.order_id = NEW.order_id;

        -- Giải phóng số Serial của thiết bị
        UPDATE devices 
        SET status = 'AVAILABLE', 
            order_detail_id = NULL,
            sold_date = NULL,
            warranty_end_date = NULL
        WHERE order_detail_id IN (SELECT order_detail_id FROM orders_details WHERE order_id = NEW.order_id);

    -- Chuyển ngược lại trạng thái đang xử lý (Trừ lại kho)
    ELSEIF OLD.status IN ('CANCELLED', 'RETURNED', 'DELIVERY_FAILED') 
           AND NEW.status NOT IN ('CANCELLED', 'RETURNED', 'DELIVERY_FAILED') THEN
        UPDATE product_variants pv
        JOIN orders_details od ON pv.variant_id = od.variant_id
        SET pv.quantity_in_stock = pv.quantity_in_stock - od.quantity,
            pv.sold_quantity = pv.sold_quantity + od.quantity
        WHERE od.order_id = NEW.order_id;

        INSERT INTO inventory_transactions (
            transaction_id,
            variant_id,
            order_id,
            type,
            quantity,
            before_quantity,
            after_quantity,
            note,
            created_by
        )
        SELECT
            UUID(),
            od.variant_id,
            NEW.order_id,
            'SOLD',
            od.quantity,
            pv.quantity_in_stock + od.quantity,
            pv.quantity_in_stock,
            CONCAT('Auto stock deduction when order status changed from ', OLD.status, ' to ', NEW.status),
            NEW.employee_id
        FROM orders_details od
        JOIN product_variants pv ON pv.variant_id = od.variant_id
        WHERE od.order_id = NEW.order_id;
    END IF;
END */;;
DELIMITER ;
