DELIMITER ;;
/*!50003 CREATE*/ /*!50003 TRIGGER `trg_orders_details_before_insert` BEFORE INSERT ON `orders_details` FOR EACH ROW BEGIN
    IF NEW.quantity <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Lỗi: Số lượng đặt hàng phải lớn hơn 0';
    END IF;
END */;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50003 TRIGGER `trg_orders_details_after_insert` AFTER INSERT ON `orders_details` FOR EACH ROW BEGIN
    DECLARE before_qty INT;

    SELECT quantity_in_stock
    INTO before_qty
    FROM product_variants
    WHERE variant_id = NEW.variant_id;

    -- Trừ kho và tăng số lượng đã bán
    -- Nếu việc trừ kho làm quantity_in_stock < 0, trigger của bảng product_variants sẽ chặn lại
    UPDATE product_variants 
    SET quantity_in_stock = quantity_in_stock - NEW.quantity,
        sold_quantity = sold_quantity + NEW.quantity
    WHERE variant_id = NEW.variant_id;

    INSERT INTO inventory_transactions (
        transaction_id,
        variant_id,
        order_id,
        type,
        quantity,
        before_quantity,
        after_quantity,
        note,
        created_by
    )
    VALUES (
        UUID(),
        NEW.variant_id,
        NEW.order_id,
        'SOLD',
        NEW.quantity,
        before_qty,
        before_qty - NEW.quantity,
        CONCAT('Auto stock deduction for order detail ', NEW.order_detail_id),
        NULL
    );
END */;;
DELIMITER ;
