/*!50003 CREATE*/ /*!50003 TRIGGER `trg_orders_details_before_update` BEFORE UPDATE ON `orders_details` FOR EACH ROW BEGIN
    IF NEW.quantity <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Lỗi: Số lượng đặt hàng phải lớn hơn 0';
    END IF;
END */;;
